   "content": "QR오더 최초 메뉴등록 신청입니다.\n상품분류별 메뉴등록 요청드립니다.\n상품 터치시 상품설명이 나오게 부탁드립니다.\nMain (상품분류)\n꾸라오로 (24000원)- 보고만 있어도 입안에 침이 꼴딱꼴딱 넘어가는 매콤새콤한 광동식 탕수육\n\n바지락 조개볶음 (22000원)- 쫄깃한 바지락에 마늘과 생강의 향을 듬뿍 담아 웍으로 볶아낸 안주로 제격인 홍콩식 바지락볶음\n상품선택시 옵션으로 면추가 선택가능하게 요청드립니다.\n\n마파두부 (18000원)- 고소하고 부드러운 두부를 감싸 안은 장소스, 산초가루와 고추기름으로 맛을 더한 마파두부\n상품선택시 옵션에 공기밥 선택가능하게 요청드립니다.\n\n유린기 (22000원)- 바삭한 닭고기에 아삭한 야채, 입맛 돋우는 소스의 어울림에 고급스러움이 더해진 닭요리\n\n가정식 동파육 (31000원)- 중국 간장과 팔각의 향이 어우러진 두툼한 삼겹과 청경채를 함께 먹는, 가정식 버전 동파육\n\n오향닭 (15000원)- 광둥 스타일의 부드러운 닭고기와 새콤달콤 오이 샐러드를 함께 먹는 닭요리\n상품선택 시 오향닭 (소), 오향닭 (중) 사이즈 선택 옵션부탁드립니다. 오향닭 (중) 선택시 +6000원 옵션부탁드립니다. \n칠리새우 (16000원)- 매콤새콤 감칠맛나는 꺼거 스페셜 칠리소스와 바삭하게 튀겨낸 오동통한 새우의 만남\n상품 선택시 칠리새우 5pc, 칠리새우 8pc(+8000원)옵션, 1pc추가 (+2800원) 옵션 선택 가능하도록 부탁드립니다.\n\n크림새우 (15000원)- 통통한 새우를 바삭하게 튀겨 입안 가득 고소, 달큰한, 한 줌 뿌린 레몬으로 상큼함을 더한 크림새우\n상품선택시 크림새우 5PC, 크림새우 8PC(+8000원)옵션, 1PC 추가(+2800원)옵션 선택 가능하게 부탁드립니다.\n\nSet menu (상품분류)\n런치세트A (오이무침+새우볶음밥+ 볶음면 택1)(36000원) - 런치세트 A 선택시 소고기볶음면(+1000원), 닭고기볶음면 (+0원)옵션 선택가능하도록 요청드립니다.\n \n런치세트B (오이무침+새우볶음밥+ 탕면 택1)(33000원) - 런치세트 B선택시 토마토탕면 (+0원), 쏸라펀 (+2000원) 옵션 선택가능하도록 요청드립니다.\n\nRice(상품분류)\n\n새우볶음밥 (11000원)- 고슬고슬 밥알과 탱글탱글 새우를 웍에 볶아내어 기본에 충실한, 참을 수 없는 볶음밥\n\n치킨 라이스 (16000원)- 각종 채소와 약재를 넣어 삶아낸 닭고기를 튀겨 특제 소스를 곁들인 홍콩식 치킨",
